package dominoes

// Domino is a single domino: two halves, each bearing a number of dots.
type Domino [2]int

// MakeChain orders the given dominoes so that the dots on one half of each
// stone match the dots on the neighboring half of an adjacent stone, and the
// two exposed ends (first and last) match each other. It returns the chain
// and true if such a chain exists, or nil and false otherwise.
func MakeChain(input []Domino) ([]Domino, bool) {
	switch len(input) {
	case 0:
		return []Domino{}, true
	case 1:
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	// Backtracking search over the unused dominoes.
	remaining := append([]Domino(nil), input...)
	var result []Domino

	var search func(chain []Domino) bool
	search = func(chain []Domino) bool {
		if len(remaining) == 0 {
			// The chain is closed only if the two exposed ends match.
			if chain[0][0] == chain[len(chain)-1][1] {
				result = append([]Domino(nil), chain...)
				return true
			}
			return false
		}

		tail := chain[len(chain)-1][1]
		for i, d := range remaining {
			// The next domino must share the chain's tail value.
			if d[0] != tail && d[1] != tail {
				continue
			}

			// Temporarily take d out of remaining.
			remaining[i] = remaining[len(remaining)-1]
			remaining = remaining[:len(remaining)-1]

			// Place d with the tail value on its left half.
			placed := d
			if d[0] != tail {
				placed = Domino{d[1], d[0]}
			}
			chain = append(chain, placed)

			if search(chain) {
				return true
			}

			// Undo the placement.
			chain = chain[:len(chain)-1]
			remaining = append(remaining, d)
		}
		return false
	}

	for i, d := range input {
		remaining[i] = remaining[len(remaining)-1]
		remaining = remaining[:len(remaining)-1]

		// Try each domino, in both orientations, as the chain's start.
		for _, first := range [][2]int{d, {d[1], d[0]}} {
			if search([]Domino{Domino(first)}) {
				return result, true
			}
		}

		remaining = append(remaining, d)
	}
	return nil, false
}

